-- قائمة المسائل القانونية، ووسمُ الموادّ بها.
--
-- المسألة «فسخ العقد للإخلال» أو «مواعيد الاعتراض على الأحكام» تقع في موادّ لا يشترك
-- نصُّها مع سؤال المحامي في لفظ. فتُوسم المواد مرّةً بمسائلها من قائمةٍ مضبوطة، ويبحث
-- المحرّك الطبقيّ في الموادّ الموسومة بمسألة السؤال بعينها.
--
-- **البذور أدناه مسودّة `draft` لم يراجعها محامٍ**، والتوسيم لا يجري إلا بالمعتمد منها،
-- والمحرّك لا يقرأ إلا وسوماً بمسائل معتمدة.
CREATE TABLE IF NOT EXISTS legal_issue_vocab (
  key         TEXT PRIMARY KEY,
  label       TEXT NOT NULL,
  layer       TEXT NOT NULL CHECK (layer IN ('substantive','procedural','evidence','general','regulation')),
  -- مجالات خريطة الإسناد مفصولةً بفاصلة، و`*` لكل المجالات.
  domains     TEXT NOT NULL DEFAULT '*',
  description TEXT NOT NULL,
  status      TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','approved','retired')),
  reviewed_by TEXT,
  reviewed_at INTEGER,
  created_at  INTEGER NOT NULL
);

CREATE TABLE IF NOT EXISTS legal_article_issues (
  seq       INTEGER NOT NULL,
  issue_key TEXT NOT NULL,
  PRIMARY KEY (seq, issue_key)
);
CREATE INDEX IF NOT EXISTS idx_article_issues_key ON legal_article_issues(issue_key, seq);

-- متى وُسمت المادة. فارغٌ = تنتظر.
ALTER TABLE legal_chunks ADD COLUMN issues_at INTEGER;
CREATE INDEX IF NOT EXISTS idx_chunks_issues_pending ON legal_chunks(seq) WHERE issues_at IS NULL;

-- نصٌّ تغيّر يُعاد وسمُه، ومقطعٌ حُذف تُحذف وسومُه.
CREATE TRIGGER IF NOT EXISTS legal_chunks_issues_reset AFTER UPDATE OF text_norm ON legal_chunks
WHEN old.text_norm IS NOT new.text_norm BEGIN
  UPDATE legal_chunks SET issues_at = NULL WHERE seq = new.seq;
END;
CREATE TRIGGER IF NOT EXISTS legal_chunks_issues_delete AFTER DELETE ON legal_chunks BEGIN
  DELETE FROM legal_article_issues WHERE seq = old.seq;
END;

